import {connectAccount,login as openAccount} from './playlists.js';
import {albumYear,formatLabel,statsMarkup,albumFacts} from './presentation.js';
import {mediaPanel,trackActions,bindMedia} from './media.js';
import {GENRES,artistsForImport,genreOf,duplicateGroups,fingerprintEqual,mergeScan,validateManifest,makeAlbum,normalize} from './core.js';
import {Repository} from './store.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const repo=new Repository({guest:true});let artistFilter='',artistLetter='',view='library',query='',genre='',format='',sort='artist',selected=null,searchToken=0,page=1,renderVersion=0;const PAGE_SIZE=50;
connectAccount(repo,()=>render());
const titleMap={library:['나의 음악 서재','앨범 서재'],artists:['','Artist Index'],review:['등록 확인함','등록 확인함'],duplicates:['같은 앨범, 다른 소장본','소장본 비교']};
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function run(fn){return async e=>{const b=e?.currentTarget;if(b?.tagName==='BUTTON')b.disabled=true;try{await fn(e);}catch(err){toast(err.message);}finally{if(b?.tagName==='BUTTON')b.disabled=false;}};}
function cover(a){a={...a,thumbnail:a.thumbnail||repo.covers.get(a.id)};const image=typeof a.thumbnail==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(a.thumbnail);return `<div class="cover">${image?`<img src="${a.thumbnail}" alt="${esc(a.title)} 커버" loading="lazy">`:`<div class="cover-placeholder"><span class="cover-type">MUSIC ARCHIVE</span><span class="initial">${esc(a.artist.slice(0,2).toUpperCase())}</span><strong>${esc(a.title)}</strong></div><span class="cover-label">커버 미등록</span>`}</div>`;}
const artistGroups=['0–9',...'ABCDEFGHIJKLMNOPQRSTUVWXYZ',...'ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ','기타'];
function artistGroup(name){const c=name.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC')[0]||'';const n=c.charCodeAt(0);return /[0-9]/.test(c)?'0–9':/[a-z]/i.test(c)?c.toUpperCase():n>=0xac00&&n<=0xd7a3?'ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ'[Math.floor((n-0xac00)/588)]:'기타';}
function filtered(){const q=normalize(query);return repo.data.albums.filter(a=>(!artistFilter||a.artist===artistFilter)&&(!q||normalize([a.title,a.artist,a.catalog_number,a.edition,a.notes,...(a.styles||[]),...(a.track_titles||[]),...(a.tracks||[]).map(t=>t.title||'')].join(' ')).includes(q))&&(!genre||genreOf(a,repo.data.artists)===genre)&&(!format||a.format?.toUpperCase()===format)).sort((a,b)=>sort==='year'?String(a.original_year||'9999').localeCompare(String(b.original_year||'9999')):sort==='recent'?String(b.created_at).localeCompare(String(a.created_at)):a.artist.localeCompare(b.artist,'ko')||String(a.original_year).localeCompare(String(b.original_year)));}
function render(){document.body.classList.toggle('guest-mode',!repo.admin);const version=++renderVersion;const all=repo.data.albums,albums=filtered(),groups=duplicateGroups(all);$('#page-title').textContent=artistFilter?artistFilter+' · 앨범':view==='library'?'':titleMap[view][0];$('#crumb').textContent=titleMap[view][1];$('#stats').innerHTML=statsMarkup(all.length,new Set(all.map(a=>a.artist)).size,all.reduce((n,a)=>n+(a.tracks?.length??a.track_titles?.length??0),0));$('#notice').textContent=repo.cloud?(repo.admin?'관리자 모드 · 등록 및 정보 수정 가능':'음악 서재 · 로그인 없이 감상할 수 있습니다.'):(all.some(a=>!a.source_id.startsWith('demo-'))?'이 기기에 저장된 서재 · 등록한 음악 정보는 이 브라우저에 저장됩니다. 다른 PC와의 동기화는 클라우드 연결이 필요합니다.':'체험 모드 · 예시 앨범입니다. 스캔 목록을 가져와 실제 음악을 등록하세요.');$('#connection-label').textContent=repo.admin?'관리자 / 로그아웃':'관리자 로그인';$('#mode-label').textContent=repo.cloud?(repo.admin?'관리자 모드':'손님용 음악 서재'):(all.some(a=>!a.source_id.startsWith('demo-'))?'이 기기의 음악 서재':'이 기기의 체험 데이터');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
let html='',visibleIds=[],totalPages=1;const pageSize=view==='artists'?100:PAGE_SIZE;const paginate=rows=>{totalPages=Math.max(1,Math.ceil(rows.length/pageSize));page=Math.max(1,Math.min(page,totalPages));return rows.slice((page-1)*pageSize,page*pageSize);};if(view==='artists'){
const counts=new Map();for(const a of all)counts.set(a.artist,(counts.get(a.artist)||0)+1);
const names=[...new Set(albums.map(a=>a.artist))].sort((a,b)=>artistGroups.indexOf(artistGroup(a))-artistGroups.indexOf(artistGroup(b))||a.localeCompare(b,'ko'));
const available=new Set(names.map(artistGroup)),chosen=names.filter(n=>!artistLetter||artistGroup(n)===artistLetter);
html=`<div class="artist-index" aria-label="아티스트 첫 글자"><button data-letter="" aria-pressed="${!artistLetter}">전체</button>${artistGroups.filter(g=>available.has(g)).map(g=>`<button data-letter="${esc(g)}" aria-pressed="${artistLetter===g}">${esc(g)}</button>`).join('')}</div><div class="artist-directory">`;
let group='';for(const n of paginate(chosen)){const g=artistGroup(n);if(g!==group){if(group)html+='</ul></section>';html+=`<section class="artist-section"><h2>${esc(g)}</h2><ul>`;group=g;}
html+=`<li><button class="artist-link" data-browse-artist="${esc(n)}">${esc(n)}</button><span>${counts.get(n)}개 앨범</span><span class="artist-genre">${esc(repo.data.artists.find(a=>a.name===n)?.genre||'미분류')}</span>${repo.admin?`<button data-artist="${esc(n)}">장르 수정</button>`:''}</li>`;}
if(group)html+='</ul></section>';html+='</div>';if(!chosen.length)html+='<p class="empty">해당 아티스트가 없습니다.</p>';$('#result-count').textContent=`${chosen.length.toLocaleString()}명의 아티스트 · 페이지당 100명`;}

else if(view==='duplicates'){const gs=duplicateGroups(albums);html=paginate(gs).map(g=>`<article class="group"><h3>${esc(g[0].artist)} · ${esc(g[0].title)}</h3><p>제목·아티스트가 같은 비교 후보입니다. 동일 판본이나 동일 음원으로 확정한 결과가 아닙니다.${g.length===2&&fingerprintEqual(g[0],g[1])?' 두 소장본의 모든 음원 파일 SHA-256이 일치합니다.':''}</p><div class="table-wrap"><table><thead><tr><th>판본 / 발매일</th><th>레이블 / 번호</th><th>형식</th><th>트랙</th><th></th></tr></thead><tbody>${g.map(a=>`<tr><td>${esc(a.edition||'미확인')}<br>${esc(a.release_year||'—')}</td><td>${esc(a.label||'—')}<br>${esc(a.catalog_number)}</td><td>${esc(formatLabel(a))}</td><td>${a.tracks?.length||'미확인'}</td><td><button data-open="${esc(a.id)}">상세 비교</button></td></tr>`).join('')}</tbody></table></div></article>`).join('');$('#result-count').textContent=`${gs.length}개 비교 그룹`;}
else{const list=view==='review'?albums.filter(a=>!a.reviewed):albums;const visible=paginate(list);visibleIds=visible.map(a=>a.id);html=`<div class="grid">${visible.map(a=>`<article class="album"><button class="album-open" data-open="${esc(a.id)}" aria-label="${esc(a.title)} 상세">${cover(a)}<h3>${esc(a.title)}</h3></button><button class="artist-name album-artist-link" data-browse-artist="${esc(a.artist)}" aria-label="${esc(a.artist)} 전체 앨범 보기">${esc(a.artist)}</button><div class="meta"><span>${esc(albumYear(a)||'연도 미확인')}</span><span>·</span><span>${esc(genreOf(a,repo.data.artists))}</span>${a.format?`<span class="badge">${esc(formatLabel(a))}</span>`:''}</div></article>`).join('')}</div>`;$('#result-count').textContent=`${list.length.toLocaleString()}개 소장본`;}
if(artistFilter)html=`<button id="back-artists" class="quiet">← 아티스트 목록</button>`+html;
$('#content').innerHTML=html&&(!html.endsWith('></div>')||albums.length)?html:'<div class="empty">표시할 자료가 없습니다.<br>검색 조건을 바꾸거나 앨범을 등록해 주세요.</div>';if(!$('#content').textContent.trim())$('#content').innerHTML='<div class="empty">표시할 자료가 없습니다.</div>';$('#pagination').innerHTML=totalPages>1?`<button id="previous-page" ${page===1?'disabled':''}>이전</button><span>${page} / ${totalPages} 페이지</span><button id="next-page" ${page===totalPages?'disabled':''}>다음</button>`:'';for(const [id,delta] of [['previous-page',-1],['next-page',1]]){const b=document.getElementById(id);if(b)b.onclick=()=>{page+=delta;render();$('#content').scrollIntoView({block:'start'});};}
if(repo.cloud&&visibleIds.some(id=>!repo.covers.has(id)))repo.loadCovers(visibleIds).then(()=>{if(version===renderVersion)render();}).catch(err=>toast('커버를 불러오지 못했습니다. '+err.message));
$('#content').querySelectorAll('[data-letter]').forEach(b=>b.onclick=()=>{artistLetter=b.dataset.letter;page=1;render();});
$('#content').querySelectorAll('[data-browse-artist]').forEach(b=>b.onclick=()=>{artistFilter=b.dataset.browseArtist;view='library';query=genre=format='';$('#search').value=$('#genre').value=$('#format').value='';page=1;render();window.scrollTo(0,0);});
if($('#back-artists'))$('#back-artists').onclick=()=>{artistFilter='';view='artists';page=1;render();};
$('#content').querySelectorAll('[data-open]').forEach(b=>b.onclick=run(()=>detail(b.dataset.open)));$('#content').querySelectorAll('[data-artist]').forEach(b=>b.onclick=()=>artistDialog(b.dataset.artist));}
function modal(title,body){searchToken++;$('#dialog-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="close" aria-label="닫기">×</button></div><div class="modal-body">${body}</div>`;$('.close').onclick=()=>$('#dialog').close();if(!$('#dialog').open)$('#dialog').showModal();}
async function detail(id){const a=await repo.getAlbum(id);if(!a)return;selected=id;modal('앨범 상세',`<div class="detail-top">${cover(a)}<div><p>${esc(a.artist)}</p><h2>${esc(a.title)}</h2>${albumFacts({...a,genre:genreOf(a,repo.data.artists)})}<div class="actions"><button id="edit">정보 수정</button><button id="lookup" class="primary">⌕ 정보 찾기</button><button id="review">${a.reviewed?'확인 취소':'확인 완료'}</button></div></div></div>${repo.admin?`<h3 class="section-title">개인 기록</h3><p class="hint">${esc(a.notes||'아직 작성한 메모가 없습니다.')}</p><h3 class="section-title">보관 위치</h3><div class="path">${esc(a.path||'경로 미등록')}</div>`:''}${mediaPanel(repo.admin)}<h3 class="section-title">트랙 · ${(a.tracks||[]).length}개</h3>${a.tracks?.length?`<div class="table-wrap"><table><thead><tr><th>#</th><th>곡명</th><th>길이</th><th>형식</th><th>가사</th><th>재생</th><th>대기열</th><th>목록</th><th>다운로드</th></tr></thead><tbody>${a.tracks.map((t,i)=>`<tr><td>${esc(t.disc||1)}-${esc(t.number||i+1)}</td><td title="${esc(t.title||t.filename)}">${esc(t.title||t.filename)}</td><td>${t.duration?Math.floor(t.duration/60)+':'+String(Math.floor(t.duration%60)).padStart(2,'0'):'—'}</td><td>${esc(formatLabel(t,a))}</td>${trackActions(i)}</tr>`).join('')}</tbody></table></div>`:'<p class="hint">파일 스캔 후 트랙 목록이 표시됩니다. 체험 자료에는 가상의 트랙을 넣지 않았습니다.</p>'}${repo.admin?`<h3 class="section-title">출처와 부속 자료</h3><div>${(a.sources||[]).map(s=>`<p class="hint">${esc(s.type)} · ${esc(s.text||'')}${/^https:\/\//.test(s.url||'')?` <a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">출처 보기 ↗</a>`:''}</p>`).join('')}${(a.attachments||[]).map(p=>`<div class="path">${esc(p)}</div>`).join('')}</div><details><summary>스캔 원본 정보 보기</summary><pre>${esc(JSON.stringify(a.raw_tags||{},null,2))}</pre></details><div class="form-actions"><button id="remove" class="danger">서재 등록 제거</button></div>`:''}`);bindMedia(repo,a);$('#edit').onclick=()=>editDialog(a);$('#lookup').onclick=()=>lookup(a);$('#review').onclick=run(async()=>{await repo.saveAlbum({...a,reviewed:!a.reviewed});render();detail(id);});if($('#remove'))$('#remove').onclick=()=>removeDialog(a);}
const editable=[['artist','아티스트'],['title','앨범명'],['original_year','원발매일 / 연도'],['release_year','소장 판본 발매일'],['edition','판본 / 에디션'],['label','레이블 / 발매사'],['catalog_number','카탈로그 번호'],['country','국가'],['performance_date','공연 / 녹음 날짜'],['venue','공연 / 녹음 장소'],['recording_source','녹음 출처 (관객·사운드보드·방송 등)']];
function editDialog(a){if(!repo.admin)return connection();modal('앨범 정보 수정',`<form id="edit-form"><div class="fields">${editable.map(([k,t])=>`<label>${t}<input name="${k}" value="${esc(a[k]||'')}" ${['title','artist'].includes(k)?'required':''} maxlength="500"></label>`).join('')}<label>관리 장르 적용<select name="genre_mode"><option value="inherit" ${a.genre_mode!=='override'?'selected':''}>아티스트 장르 따르기</option><option value="override" ${a.genre_mode==='override'?'selected':''}>이 앨범만 직접 지정</option></select></label><label>앨범 관리 장르<select name="genre">${GENRES.map(g=>`<option ${g===a.genre?'selected':''}>${g}</option>`).join('')}</select></label><label class="full">세부 장르·스타일 (쉼표로 구분)<input name="styles" value="${esc((a.styles||[]).join(', '))}"></label><label class="full">개인 메모<textarea name="notes" rows="4">${esc(a.notes)}</textarea></label></div><p class="hint">수정한 항목은 재스캔으로 덮어쓰지 않습니다. 원본 음원 태그는 변경하지 않습니다.</p><div class="form-actions"><button type="submit" class="primary">변경 저장</button></div></form>`);$('#edit-form').onsubmit=run(async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.styles=f.styles.split(',').map(x=>x.trim()).filter(Boolean);const changed=Object.keys(f).filter(k=>JSON.stringify(f[k])!==JSON.stringify(a[k]??''));const next={...a,...f,manual_fields:[...new Set([...(a.manual_fields||[]),...changed])]};if(!repo.data.artists.some(x=>x.name===f.artist))await repo.saveArtist(f.artist,'미분류');await repo.saveAlbum(next);render();detail(a.id);toast('수정한 정보를 저장했습니다.');});}
function artistDialog(name){if(!repo.admin)return connection();const artist=repo.data.artists.find(a=>a.name===name);modal(name,`<p class="hint">‘아티스트 장르 따르기’ 상태의 앨범에 적용됩니다. 개별 지정한 앨범은 유지됩니다.</p><form id="artist-form"><label>대표 관리 장르 <select name="genre">${GENRES.map(g=>`<option ${g===(artist?.genre||'미분류')?'selected':''}>${g}</option>`).join('')}</select></label><div class="form-actions"><button class="primary">저장</button></div></form>`);$('#artist-form').onsubmit=run(async e=>{e.preventDefault();await repo.saveArtist(name,new FormData(e.target).get('genre'));$('#dialog').close();render();toast('대표 장르를 저장했습니다.');});}
function removeDialog(a){if(!repo.admin)return connection();modal('서재 등록 제거',`<p><strong>${esc(a.artist)} — ${esc(a.title)}</strong></p><p class="hint">서재의 정보와 개인 메모만 제거합니다. NAS의 실제 음원은 삭제하지 않습니다. 파일이 남아 있으면 재스캔 시 다시 등록됩니다.</p><div class="form-actions"><button id="cancel-remove">돌아가기</button><button id="confirm-remove" class="danger">등록 정보 제거</button></div>`);$('#cancel-remove').onclick=()=>detail(a.id);$('#confirm-remove').onclick=run(async()=>{await repo.removeAlbum(a.id);$('#dialog').close();render();toast('서재에서 제거했습니다. 원본 파일은 유지됩니다.');});}
function connection(){modal('관리자 로그인',`<p class="hint">감상에는 로그인이 필요 없습니다. 앨범 등록·수정·삭제 시에만 관리자 계정으로 로그인하세요.</p><form id="connect-form"><div class="fields"><label>이메일<input name="email" type="email" required autocomplete="username"></label><label>비밀번호<input name="password" type="password" required autocomplete="current-password"></label></div><p class="hint">관리자 로그인은 현재 페이지에서만 유지됩니다. 비밀번호는 저장하지 않습니다.</p><p id="login-error" class="hint error" role="alert"></p><div class="form-actions">${repo.admin?'<button type="button" id="logout">로그아웃</button>':''}<button class="primary" type="submit">관리자 로그인</button></div></form>`);$('#connect-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type=submit]');b.disabled=true;b.textContent='로그인 중…';const f=Object.fromEntries(new FormData(e.target));try{await repo.login(repo.config.url,repo.config.key,f.email.trim(),f.password);$('#dialog').close();render();}catch(err){$('#login-error').textContent=err.message;}finally{b.disabled=false;b.textContent='관리자 로그인';}};if($('#logout'))$('#logout').onclick=run(async()=>{try{await repo.logout();}finally{$('#dialog').close();location.reload();}});}
function importDialog(){if(!repo.admin)return connection();modal('앨범 등록',`<p>NAS에서 읽기 전용 스캐너를 실행해 만든 JSON 목록을 가져옵니다.</p><p class="hint">경로·태그·CUE·커버 정보가 등록됩니다. 같은 보관 위치의 재스캔은 기존 기록을 갱신하고, 직접 수정한 값은 보존합니다.</p><div class="actions"><button id="choose-file" class="primary">스캔 목록 선택</button><button id="manual-add">직접 앨범 추가</button></div><p class="hint">${repo.cloud?'현재 클라우드 서재에 등록됩니다.':'현재는 이 기기의 서재에 등록됩니다. 대규모 목록은 Supabase 연결 후 가져오세요.'}</p><div id="import-status" role="status"></div>`);$('#choose-file').onclick=()=>{$('#import-file').value='';$('#import-file').click();};$('#manual-add').onclick=()=>editDialog(makeAlbum({source_id:'manual:'+crypto.randomUUID(),artist:'',title:'',path:'직접 등록'}));}
async function importFile(file){if(!file)return;if(file.size>100*1024*1024)throw Error('100MB 이하 목록으로 나누어 가져오세요.');const m=validateManifest(JSON.parse(await file.text()));modal('가져오기 확인',`<p><strong>${m.albums.length.toLocaleString()}개 소장본</strong>을 ${repo.cloud?'클라우드':'이 기기의 서재'}에 등록합니다.</p><p class="hint">동일한 source_id는 갱신하고 개인 수정은 유지합니다. 목록에 없는 기존 앨범은 삭제하지 않습니다. 내보낸 아티스트 장르도 복원하며, 현재 서재에 이미 있는 아티스트의 장르는 유지합니다.</p><div class="form-actions"><button id="start-import" class="primary">가져오기 시작</button></div><p id="import-progress" role="status"></p>`);$('#start-import').onclick=run(async()=>{let done=0;const dialog=$('#dialog'),close=$('.close'),progress=$('#import-progress');const preventClose=e=>e.preventDefault();dialog.addEventListener('cancel',preventClose);close.disabled=true;try{for(const artist of artistsForImport(m,repo.data.artists))await repo.saveArtist(artist.name,artist.genre);for(const raw of m.albums){const match=repo.data.albums.find(a=>a.source_id===raw.source_id);const existing=match?await repo.getAlbum(match.id):null;const a=mergeScan(existing,makeAlbum(raw));if(!repo.data.artists.some(x=>x.name===a.artist))await repo.saveArtist(a.artist,'미분류');await repo.saveAlbum(a);done++;$('#import-progress').textContent=`${done} / ${m.albums.length} 저장 완료`;if(done%20===0)await new Promise(r=>setTimeout(r,0));}render();modal('가져오기 완료',`<p role="status"><strong>${done.toLocaleString()}개 소장본을 저장했습니다.</strong></p><p class="hint">확인을 누르면 앨범 서재로 돌아갑니다.</p><div class="form-actions"><button id="finish-import" class="primary">확인</button></div>`);$('#finish-import').onclick=()=>{$('#dialog').close();$('#import').focus();};$('#finish-import').focus();}catch(err){render();progress.textContent=`${done} / ${m.albums.length}개 저장 후 중단되었습니다. ${err.message} 저장된 항목은 유지되며, 같은 파일로 다시 시도할 수 있습니다.`;progress.setAttribute('role','alert');throw err;}finally{dialog.removeEventListener('cancel',preventClose);close.disabled=false;}});}
let lastSearch=0;
function lookup(a){if(!repo.admin)return connection();modal('앨범 정보 찾기',`<p class="hint">폴더와 태그에서 얻은 단서로 후보를 찾습니다. 공연이나 곡이 같아도 같은 판본으로 확정하지 않습니다.</p><form id="lookup-form" class="fields"><label>아티스트<input name="artist" value="${esc(a.artist)}" required></label><label>앨범명 또는 검색 단서<input name="title" value="${esc(a.title)}" required></label><div class="full actions"><button type="submit" class="primary">MusicBrainz 후보 검색</button><a href="https://www.discogs.com/search/?q=${encodeURIComponent([a.artist,a.title,a.catalog_number].filter(Boolean).join(' '))}&type=release" target="_blank" rel="noopener noreferrer">Discogs에서 찾기 ↗</a><a href="https://www.google.com/search?q=${encodeURIComponent([a.artist,a.title,a.performance_date,a.venue,'bootleg discography'].filter(Boolean).join(' '))}" target="_blank" rel="noopener noreferrer">공연·부틀랙 웹 검색 ↗</a></div></form><p class="hint">기본 후보 검색과 선택 반영을 지원합니다. 북클릿 OCR·오디오 지문·팬 아카이브 자동 조사는 후속 개발 항목입니다.</p><div id="lookup-results" aria-live="polite"></div>`);const token=searchToken;$('#lookup-form').onsubmit=run(async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const box=$('#lookup-results');box.innerHTML='<p class="loading">발매 정보를 찾고 있습니다…</p>';const delay=Math.max(0,1100-(Date.now()-lastSearch));await new Promise(r=>setTimeout(r,delay));lastSearch=Date.now();const clean=s=>s.replace(/["\\:()\[\]{}~^!+?*]/g,' ');const q=`artist:"${clean(f.artist)}" AND release:"${clean(f.title)}"`;try{const res=await fetch('https://musicbrainz.org/ws/2/release/?fmt=json&limit=10&query='+encodeURIComponent(q),{headers:{Accept:'application/json'}});if(!res.ok)throw Error('MusicBrainz 검색 응답이 지연되거나 제한되었습니다. 외부 검색 링크를 이용해 주세요.');const result=await res.json();if(searchToken!==token)return;const rows=result.releases||[];box.innerHTML=rows.length?rows.map((r,i)=>`<article class="candidate"><h3>${esc(r.title)}</h3><p>${esc(r.date||'날짜 미상')} · ${esc(r.country||'국가 미상')} · ${esc(r.status||'상태 미상')}</p><p>${esc((r['label-info']||[]).map(l=>[l.label?.name,l['catalog-number']].filter(Boolean).join(' / ')).join(', '))}</p><p>출처의 검색 점수: ${esc(r.score??'—')} · 판본 일치 확률이 아닙니다.</p><div class="actions"><a href="https://musicbrainz.org/release/${encodeURIComponent(r.id)}" target="_blank" rel="noopener noreferrer">원문 확인 ↗</a><button data-candidate="${i}">반영 항목 선택</button></div></article>`).join(''):'<p class="hint">검색된 후보가 없습니다. 제목을 줄이거나 공연 날짜·장소로 웹 검색을 해보세요. 기존 정보는 유지됩니다.</p>';box.querySelectorAll('[data-candidate]').forEach(b=>b.onclick=()=>applyCandidate(a,rows[Number(b.dataset.candidate)]));}catch(err){if(searchToken===token)box.textContent=err.message;}});}
function applyCandidate(a,r){const label=r['label-info']?.[0];const fields={title:r.title,release_year:r.date||'',country:r.country||'',label:label?.label?.name||'',catalog_number:label?.['catalog-number']||''};modal('외부 정보 선택 반영',`<p class="hint">필요한 항목만 선택하세요. 직접 수정한 항목은 기본적으로 선택하지 않습니다. 후보를 연결해도 판본이 확인 완료로 바뀌지는 않습니다.</p><form id="candidate-form">${Object.entries(fields).filter(([,v])=>v).map(([k,v])=>`<p><label class="check"><input type="checkbox" name="${k}" ${!(a.manual_fields||[]).includes(k)?'checked':''}>${esc(editable.find(([x])=>x===k)?.[1]||k)}: ${esc(a[k]||'미확인')} → <strong>${esc(v)}</strong></label></p>`).join('')}<div class="form-actions"><button class="primary">선택한 정보 저장</button></div></form>`);$('#candidate-form').onsubmit=run(async e=>{e.preventDefault();const keys=[...new FormData(e.target).keys()];const updated={...a,manual_fields:[...new Set([...(a.manual_fields||[]),...keys])],sources:[...(a.sources||[]),{type:'MusicBrainz',url:'https://musicbrainz.org/release/'+r.id,text:'사용자가 선택한 후보 정보',checked_at:new Date().toISOString(),fields:keys}]};for(const k of keys)updated[k]=fields[k];await repo.saveAlbum(updated);render();detail(a.id);toast('선택한 정보와 출처를 저장했습니다.');});}
$('#genre').innerHTML='<option value="">모든 장르</option>'+GENRES.map(g=>`<option>${g}</option>`).join('');$('#search').oninput=e=>{query=e.target.value;page=1;render();};$('#genre').onchange=e=>{genre=e.target.value;page=1;render();};$('#format').onchange=e=>{format=e.target.value;page=1;render();};$('#sort').onchange=e=>{sort=e.target.value;page=1;render();};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;artistFilter='';artistLetter='';page=1;render();});$('#settings').onclick=openAccount;$('#import').onclick=importDialog;$('#import-file').onchange=run(e=>importFile(e.target.files[0]));$('#export').onclick=run(async()=>{const exported=await repo.exportData();const blob=new Blob([JSON.stringify({schema_version:1,exported_at:new Date().toISOString(),artists:exported.artists,albums:exported.albums},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='music-library-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('개인 기록을 포함한 목록을 내보냈습니다.');});
repo.onCatalogUpdate=()=>render();
repo.onCatalogError=message=>{$('#notice').textContent=message;};
$('#refresh-catalog').onclick=run(async()=>{await repo.load({force:true});render();toast('최신 목록으로 갱신했습니다.');});
repo.onProgress=count=>{$('#notice').textContent=`앨범 목록을 불러오는 중 · ${count.toLocaleString()}개 확인`;};
$('#notice').textContent='앨범 목록을 불러오는 중입니다…';
try{await repo.load();render();}catch(err){render();$('#notice').textContent='서재 자동 연결을 준비 중입니다. 잠시 후 새로고침해 주세요. 관리자는 로그인해 이용할 수 있습니다.';if(!repo.data.albums.length)$('#content').textContent=err.message;else $('#notice').textContent='불러온 목록을 표시합니다. 나머지 목록은 목록 새로고침으로 다시 불러올 수 있습니다.';}
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'search_music_library',description:'현재 로그인한 서재를 검색하고 화면에 표시합니다. 원본은 수정하지 않습니다.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:async input=>{if(typeof input?.query!=='string')throw Error('query 문자열이 필요합니다.');query=input.query;page=1;$('#search').value=query;view='library';render();return filtered().slice(0,30).map(({id,artist,title,edition})=>({id,artist,title,edition}));}});}catch{}}

$('.brand').onclick=e=>{e.preventDefault();view='library';artistFilter=artistLetter=query=genre=format='';sort='artist';page=1;for(const id of ['search','genre','format'])$('#'+id).value='';$('#sort').value='artist';$('#dialog').close();render();window.scrollTo({top:0,behavior:'instant'});};
